  1→//! Feedback delivery via GitHub issues or email.
  2→//!
  3→//! Routes feedback to the appropriate external channel:
  4→//! - Bug and feature reports → GitHub issue (browser-based, no token required)
  5→//! - UX and other feedback → Email via mailto link
  6→
  7→use crate::secrets::{OutputMasker, SecretMatcher};
  8→use crate::session::Session;
  9→
 10→use super::FeedbackEntry;
 11→
 12→/// Target repository for GitHub issues.
 13→const GITHUB_REPO: &str = "bivvy-dev/bivvy";
 14→
 15→/// Email address for non-GitHub feedback.
 16→const FEEDBACK_EMAIL: &str = "hello@bivvy.dev";
 17→
 18→/// Maximum URL length before truncation (browsers have ~8000 char limits).
 19→const MAX_URL_LEN: usize = 8000;
 20→
 21→/// How feedback should be delivered externally.
 22→#[derive(Debug, Clone, PartialEq)]
 23→pub enum DeliveryMethod {
 24→    /// Open a pre-filled GitHub issue in the browser.
 25→    GitHubIssue { labels: Vec<String> },
 26→    /// Open a mailto link in the default mail client.
 27→    Email { to: String },
 28→}
 29→
 30→/// Determine the delivery method based on feedback category.
 31→pub fn determine_method(category: &str) -> DeliveryMethod {
 32→    match category {
 33→        "bug" => DeliveryMethod::GitHubIssue {
 34→            labels: vec!["bug".to_string(), "user-feedback".to_string()],
 35→        },
 36→        "feature" => DeliveryMethod::GitHubIssue {
 37→            labels: vec!["enhancement".to_string(), "user-feedback".to_string()],
 38→        },
 39→        "ux" => DeliveryMethod::Email {
 40→            to: FEEDBACK_EMAIL.to_string(),
 41→        },
 42→        _ => DeliveryMethod::Email {
 43→            to: FEEDBACK_EMAIL.to_string(),
 44→        },
 45→    }
 46→}
 47→
 48→/// Build the issue/email title from a feedback entry.
 49→pub fn build_title(entry: &FeedbackEntry, category: &str) -> String {
 50→    let msg = if entry.message.len() > 60 {
 51→        format!("{}...", &entry.message[..60])
 52→    } else {
 53→        entry.message.clone()
 54→    };
 55→    format!("[{}] {}", category, msg)
 56→}
 57→
 58→/// Build the GitHub issue body from a feedback entry and optional session.
 59→pub fn build_github_body(entry: &FeedbackEntry, session: Option<&Session>) -> String {
 60→    let mut sections = Vec::new();
 61→
 62→    // Feedback section (always present)
 63→    sections.push(format!("## Feedback\n\n{}", entry.message));
 64→
 65→    // Context section
 66→    let version = env!("CARGO_PKG_VERSION");
 67→    let os = std::env::consts::OS;
 68→    let arch = std::env::consts::ARCH;
 69→
 70→    let mut context_lines = vec![format!("- **Bivvy:** {} · {} {}", version, os, arch)];
 71→
 72→    if let Some(session) = session {
 73→        let meta = &session.metadata;
 74→        let args_str = if meta.args.is_empty() {
 75→            String::new()
 76→        } else {
 77→            format!(" {}", meta.args.join(" "))
 78→        };
 79→        let exit_str = meta
 80→            .exit_code
 81→            .map(|c| format!(" → exit {}", c))
 82→            .unwrap_or_default();
 83→        context_lines.push(format!(
 84→            "- **Command:** `bivvy {}{}`{}",
 85→            meta.command, args_str, exit_str
 86→        ));
 87→
 88→        if let Some(ref hash) = meta.config_hash {
 89→            let step_count = meta.context.step_results.len();
 90→            context_lines.push(format!(
 91→                "- **Config:** {} ({} steps)",
 92→                &hash[..hash.len().min(8)],
 93→                step_count
 94→            ));
 95→        }
 96→    }
 97→
 98→    sections.push(format!("## Context\n\n{}", context_lines.join("\n")));
 99→
100→    // Step results table (only if session has steps)
101→    if let Some(session) = session {
102→        let steps = &session.metadata.context.step_results;
103→        if !steps.is_empty() {
104→            let mut table = String::from("## Step Results\n\n");
105→            table.push_str("| Step | Status | Duration |\n");
106→            table.push_str("|------|--------|----------|\n");
107→            for step in steps {
108→                let duration = step
109→                    .duration_ms
110→                    .map(|ms| format!("{:.1}s", ms as f64 / 1000.0))
111→                    .unwrap_or_else(|| "-".to_string());
112→                table.push_str(&format!(
113→                    "| {} | {} | {} |\n",
114→                    step.name, step.status, duration
115→                ));
116→            }
117→            sections.push(table);
118→        }
119→    }
120→
121→    // Errors section (only if present)
122→    if let Some(session) = session {
123→        let errors = &session.metadata.context.errors;
124→        if !errors.is_empty() {
125→            let error_text = errors.join("\n");
126→            // Truncate long error text
127→            let truncated = if error_text.len() > 2000 {
128→                format!("{}...\n(truncated)", &error_text[..2000])
129→            } else {
130→                error_text
131→            };
132→            sections.push(format!("## Errors\n\n```\n{}\n```", truncated));
133→        }
134→    }
135→
136→    // Footer
137→    sections.push(
138→        "---\n*Submitted via `bivvy feedback` · [bivvy docs](https://bivvy.dev)*".to_string(),
139→    );
140→
141→    sections.join("\n\n")
142→}
143→
144→/// Build the email subject line.
145→pub fn build_email_subject(entry: &FeedbackEntry, category: &str) -> String {
146→    let msg = if entry.message.len() > 50 {
147→        format!("{}...", &entry.message[..50])
148→    } else {
149→        entry.message.clone()
150→    };
151→    format!("[bivvy {}] {}", category, msg)
152→}
153→
154→/// Build the email body as plain text.
155→pub fn build_email_body(entry: &FeedbackEntry, session: Option<&Session>) -> String {
156→    let mut lines = Vec::new();
157→
158→    lines.push(format!("Feedback: {}", entry.message));
159→    lines.push(String::new());
160→
161→    let version = env!("CARGO_PKG_VERSION");
162→    let os = std::env::consts::OS;
163→    let arch = std::env::consts::ARCH;
164→    lines.push(format!("Bivvy: {} · {} {}", version, os, arch));
165→
166→    if let Some(session) = session {
167→        let meta = &session.metadata;
168→        let args_str = if meta.args.is_empty() {
169→            String::new()
170→        } else {
171→            format!(" {}", meta.args.join(" "))
172→        };
173→        let exit_str = meta
174→            .exit_code
175→            .map(|c| format!(" → exit {}", c))
176→            .unwrap_or_default();
177→        lines.push(format!(
178→            "Command: bivvy {}{}{}",
179→            meta.command, args_str, exit_str
180→        ));
181→
182→        let steps = &meta.context.step_results;
183→        if !steps.is_empty() {
184→            lines.push(String::new());
185→            lines.push("Steps:".to_string());
186→            for step in steps {
187→                let duration = step
188→                    .duration_ms
189→                    .map(|ms| format!(" ({:.1}s)", ms as f64 / 1000.0))
190→                    .unwrap_or_default();
191→                lines.push(format!("  {} - {}{}", step.name, step.status, duration));
192→            }
193→        }
194→
195→        let errors = &meta.context.errors;
196→        if !errors.is_empty() {
197→            lines.push(String::new());
198→            lines.push("Errors:".to_string());
199→            for err in errors {
200→                lines.push(format!("  {}", err));
201→            }
202→        }
203→    }
204→
205→    lines.push(String::new());
206→    lines.push("Sent via bivvy feedback".to_string());
207→
208→    lines.join("\n")
209→}
210→
211→/// Build a pre-filled GitHub issue URL.
212→pub fn build_github_url(title: &str, body: &str, labels: &[String]) -> String {
213→    let encoded_title = urlencoding::encode(title);
214→    let encoded_labels = labels.join(",");
215→    let encoded_labels = urlencoding::encode(&encoded_labels);
216→
217→    // Start with everything except body to measure remaining space
218→    let prefix = format!(
219→        "https://github.com/{}/issues/new?title={}&labels={}",
220→        GITHUB_REPO, encoded_title, encoded_labels
221→    );
222→
223→    let body_budget = MAX_URL_LEN.saturating_sub(prefix.len() + "&body=".len());
224→    let encoded_body = urlencoding::encode(body);
225→
226→    let final_body = if encoded_body.len() > body_budget {
227→        // Truncate the raw body, then re-encode
228→        let mut truncated = body.to_string();
229→        // Binary search for the right truncation point
230→        while urlencoding::encode(&truncated).len() > body_budget {
231→            // Remove roughly 10% or 100 chars, whichever is larger
232→            let remove = (truncated.len() / 10).max(100).min(truncated.len());
233→            truncated.truncate(truncated.len() - remove);
234→        }
235→        if truncated.len() < body.len() {
236→            truncated.push_str("\n\n(truncated)");
237→        }
238→        urlencoding::encode(&truncated).into_owned()
239→    } else {
240→        encoded_body.into_owned()
241→    };
242→
243→    format!("{}&body={}", prefix, final_body)
244→}
245→
246→/// Build a mailto URL.
247→pub fn build_mailto_url(to: &str, subject: &str, body: &str) -> String {
248→    let encoded_subject = urlencoding::encode(subject);
249→    let encoded_body = urlencoding::encode(body);
250→    format!(
251→        "mailto:{}?subject={}&body={}",
252→        to, encoded_subject, encoded_body
253→    )
254→}
255→
256→/// Scrub sensitive content from text before sending externally.
257→///
258→/// Masks:
259→/// - Environment variable values matching secret patterns
260→/// - Home directory paths
261→/// - Usernames in paths
262→pub fn scrub_payload(text: &str) -> String {
263→    if text.is_empty() {
264→        return String::new();
265→    }
266→
267→    let mut masker = OutputMasker::new();
268→    let matcher = SecretMatcher::with_builtins();
269→
270→    // Collect secret env var values
271→    for (key, value) in std::env::vars() {
272→        if matcher.is_secret(&key) && !value.is_empty() {
273→            masker.add_secret(value);
274→        }
275→    }
276→
277→    let mut result = masker.mask(text);
278→
279→    // Replace home directory
280→    if let Some(home) = dirs::home_dir() {
281→        let home_str = home.display().to_string();
282→        if !home_str.is_empty() {
283→            result = result.replace(&home_str, "~");
284→        }
285→    }
286→
287→    // Replace username in paths (e.g., /home/username/ or /Users/username/)
288→    if let Some(home) = dirs::home_dir() {
289→        if let Some(username) = home.file_name() {
290→            let username_str = username.to_string_lossy();
291→            // Only replace in path-like contexts
292→            let patterns = [
293→                format!("/home/{}/", username_str),
294→                format!("/Users/{}/", username_str),
295→                format!("\\Users\\{}\\", username_str),
296→                format!("/home/{}", username_str),
297→                format!("/Users/{}", username_str),
298→            ];
299→            for pattern in &patterns {
300→                let replacement = pattern.replace(&*username_str, "<user>");
301→                result = result.replace(pattern, &replacement);
302→            }
303→        }
304→    }
305→
306→    result
307→}
308→
309→/// Open a URL in the default browser or mail client.
310→pub fn open_url(url: &str) -> anyhow::Result<()> {
311→    open::that(url).map_err(|e| {
312→        anyhow::anyhow!(
313→            "Failed to open URL. You can open it manually:\n  {}\n\nError: {}",
314→            url,
315→            e
316→        )
317→    })
318→}
