320→/// Build a delivery preview string for showing to the user before they confirm.
321→pub fn build_preview(
322→    entry: &FeedbackEntry,
323→    category: &str,
324→    session: Option<&Session>,
325→    method: &DeliveryMethod,
326→) -> String {
327→    let title = build_title(entry, category);
328→
329→    let body = match method {
330→        DeliveryMethod::GitHubIssue { .. } => build_github_body(entry, session),
331→        DeliveryMethod::Email { .. } => build_email_body(entry, session),
332→    };
333→
334→    let scrubbed_body = scrub_payload(&body);
335→
336→    let target_description = match method {
337→        DeliveryMethod::GitHubIssue { .. } => {
338→            format!("This will open a GitHub issue on {}.", GITHUB_REPO)
339→        }
340→        DeliveryMethod::Email { to } => {
341→            format!("This will open an email to {}.", to)
342→        }
343→    };
344→
345→    format!(
346→        "  ┌─ What we'll send ─────────────────────────────\n  \
347→         │\n  \
348→         │  Title: {}\n  \
349→         │\n  \
350→         │  {}\n  \
351→         │\n  \
352→         │  NO env vars, secrets, or file paths — just the above.\n  \
353→         │\n  \
354→         └────────────────────────────────────────────────\n\n  \
355→         {}",
356→        title,
357→        scrubbed_body.replace('\n', "\n  │  "),
358→        target_description,
359→    )
360→}
