//! Centralized user-level directory resolution using platform-standard paths.
//!
//! Instead of hardcoding `~/.bivvy/` for all user data, this module uses
//! the platform's standard directories:
//!
//! | Purpose          | Linux / XDG              | macOS                          | Windows                   |
//! |------------------|--------------------------|--------------------------------|---------------------------|
//! | Config           | `~/.config/bivvy/`       | `~/Library/Application Support/bivvy/` | `%APPDATA%/bivvy/` |
//! | Data (state, etc)| `~/.local/share/bivvy/`  | `~/Library/Application Support/bivvy/` | `%APPDATA%/bivvy/` |
//! | Sessions         | `~/.local/share/bivvy/`  | `~/Library/Application Support/bivvy/` | `%LOCALAPPDATA%/bivvy/` |
//!
//! Project-level `.bivvy/` directories are unaffected — they remain
//! relative to the project root.

use std::path::PathBuf;

/// Application name used as the subdirectory in platform directories.
const APP_NAME: &str = "bivvy";

/// User-level config directory for Bivvy.
///
/// Returns the platform-standard config directory with `bivvy/` appended:
/// - Linux: `$XDG_CONFIG_HOME/bivvy/` (default `~/.config/bivvy/`)
/// - macOS: `~/Library/Application Support/bivvy/`
/// - Windows: `%APPDATA%/bivvy/`
pub fn config_dir() -> Option<PathBuf> {
    dirs::config_dir().map(|d| d.join(APP_NAME))
}

/// User-level data directory for Bivvy.
///
/// Used for persistent state, project index, templates, and failure reports.
///
/// Returns the platform-standard data directory with `bivvy/` appended:
/// - Linux: `$XDG_DATA_HOME/bivvy/` (default `~/.local/share/bivvy/`)
/// - macOS: `~/Library/Application Support/bivvy/`
/// - Windows: `%APPDATA%/bivvy/`
pub fn data_dir() -> Option<PathBuf> {
    dirs::data_dir().map(|d| d.join(APP_NAME))
}

/// User global config file path.
///
/// Returns `<config_dir>/config.yml`.
pub fn user_config_file() -> Option<PathBuf> {
    config_dir().map(|d| d.join("config.yml"))
}

/// Directory for project state storage.
///
/// Returns `<data_dir>/projects/`.
pub fn projects_dir() -> Option<PathBuf> {
    data_dir().map(|d| d.join("projects"))
}

/// Project index file path.
///
/// Returns `<data_dir>/projects/index.yml`.
pub fn project_index_file() -> Option<PathBuf> {
    projects_dir().map(|d| d.join("index.yml"))
}

/// State directory for a specific project.
///
/// Returns `<data_dir>/projects/<hash>/`.
pub fn project_state_dir(project_hash: &str) -> Option<PathBuf> {
    projects_dir().map(|d| d.join(project_hash))
}

/// User-level templates directory.
///
/// Returns `<data_dir>/templates/`.
pub fn user_templates_dir() -> Option<PathBuf> {
    data_dir().map(|d| d.join("templates"))
}

/// Failure reports directory.
///
/// Returns `<data_dir>/failure-reports/`.
pub fn failure_reports_dir() -> Option<PathBuf> {
    data_dir().map(|d| d.join("failure-reports"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn config_dir_ends_with_bivvy() {
        if let Some(dir) = config_dir() {
            assert!(
                dir.ends_with("bivvy"),
                "config_dir should end with 'bivvy': {:?}",
                dir
            );
        }
    }

    #[test]
    fn data_dir_ends_with_bivvy() {
        if let Some(dir) = data_dir() {
            assert!(
                dir.ends_with("bivvy"),
                "data_dir should end with 'bivvy': {:?}",
                dir
            );
        }
    }

    #[test]
    fn config_dir_does_not_use_home_dot_bivvy() {
        if let Some(dir) = config_dir() {
            let dir_str = dir.to_string_lossy();
            assert!(
                !dir_str.contains(".bivvy"),
                "config_dir should not contain '.bivvy': {:?}",
                dir
            );
        }
    }

    #[test]
    fn data_dir_does_not_use_home_dot_bivvy() {
        if let Some(dir) = data_dir() {
            let dir_str = dir.to_string_lossy();
            assert!(
                !dir_str.contains(".bivvy"),
                "data_dir should not contain '.bivvy': {:?}",
                dir
            );
        }
    }

    #[test]
    fn user_config_file_path() {
        if let Some(path) = user_config_file() {
            assert!(path.ends_with("config.yml"));
            assert!(path.parent().unwrap().ends_with("bivvy"));
        }
    }

    #[test]
    fn projects_dir_path() {
        if let Some(dir) = projects_dir() {
            assert!(dir.ends_with("projects"));
        }
    }

    #[test]
    fn project_index_file_path() {
        if let Some(path) = project_index_file() {
            assert!(path.ends_with("index.yml"));
            assert!(path.parent().unwrap().ends_with("projects"));
        }
    }

    #[test]
    fn project_state_dir_path() {
        if let Some(dir) = project_state_dir("abc123") {
            assert!(dir.ends_with("abc123"));
            assert!(dir.parent().unwrap().ends_with("projects"));
        }
    }

    #[test]
    fn user_templates_dir_path() {
        if let Some(dir) = user_templates_dir() {
            assert!(dir.ends_with("templates"));
            let dir_str = dir.to_string_lossy();
            assert!(
                !dir_str.contains(".bivvy"),
                "user_templates_dir should not contain '.bivvy': {:?}",
                dir
            );
        }
    }

    #[test]
    fn failure_reports_dir_path() {
        if let Some(dir) = failure_reports_dir() {
            assert!(dir.ends_with("failure-reports"));
            let dir_str = dir.to_string_lossy();
            assert!(
                !dir_str.contains(".bivvy"),
                "failure_reports_dir should not contain '.bivvy': {:?}",
                dir
            );
        }
    }

    #[test]
    fn config_dir_differs_from_home_dot_bivvy() {
        // Verify config_dir uses the platform config directory, not home
        if let (Some(config), Some(home)) = (config_dir(), dirs::home_dir()) {
            let old_path = home.join(".bivvy");
            assert_ne!(
                config, old_path,
                "config_dir should not equal ~/.bivvy"
            );
        }
    }

    #[test]
    fn data_dir_differs_from_home_dot_bivvy() {
        // Verify data_dir uses the platform data directory, not home
        if let (Some(data), Some(home)) = (data_dir(), dirs::home_dir()) {
            let old_path = home.join(".bivvy");
            assert_ne!(
                data, old_path,
                "data_dir should not equal ~/.bivvy"
            );
        }
    }
}

